mapper.select:
select t.spec_name,t.spec_name specName,t.event_way,t.event_way eventWay,t.key_id,t.key_id
keyId,t.spec_cd,t.spec_cd specCd,t.remark,t.status_cd,t.status_cd statusCd
from event_template_param_key t
where 1 =1

    and t.spec_name= #{specName}


    and t.event_way= #{eventWay}


    and t.key_id= #{keyId}


    and t.spec_cd= #{specCd}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

